  'player.mirror.h2h': [BK, "{ key: 'vs', label:"],
  'player.mirror.stamp': [BK, '<BucketsPickStamp'], 'player.stamp': [BK, '<BucketsPickStamp'],
  'player.mirror.props': [BK, '<PlayerBars log='],  // 10-21: the props grid folded into THE BARS (components/buckets/PlayerBars.js)
